from taf.collectors.core import Decorating, NamedComponentFactory, StartableCollector
from taf.sbts.oam.coam.admin import AdminConnection


class ClassicalGnbSyslogCollector(Decorating, StartableCollector):

    def __init__(self, **kwargs):
        super(ClassicalGnbSyslogCollector, self).__init__(**kwargs)

    def _setup(self):
        admin_connection = self._create_admin_connection()

        params_5gcpnrt = [{"name": "logLevelRadParam", "value": "2"}]
        admin_connection.set_multiple_rad_debug_parameters(domain="5GCPNRT",
                                                           persistency="Persistent",
                                                           rad_parameters=params_5gcpnrt)

        log_components = [
            "rdLogSeverityCpNb",
            "rdLogSeverityCpSb",
            "rdLogSeverityCpUe",
            "rdLogSeverityCpCl",
            "rdLogSeverityCpIf",
            "rdLogSeverityCpSctp",
            "rdLogSeverityCpE2"]

        params_5gcpcu = [{"name": name, "value": "2"} for name in log_components]
        params_5gcpcu.append({"name": "sctpDiagnosticsEnable", "value": "false"})

        admin_connection.set_multiple_rad_debug_parameters(domain="5GCPCU",
                                                           rad_parameters=params_5gcpcu,
                                                           persistency="Persistent")

        admin_connection.disconnect()

    def _start(self):
        self._collector._start()

    def _stop(self):
        self._collector._stop()

    @staticmethod
    def _create_admin_connection():
        return AdminConnection()


class ClassicalGnbSyslogCollectorFactory(NamedComponentFactory):
    _product_class = ClassicalGnbSyslogCollector
